import numpy as np

def feature(item, bins, capacity):
    """+1 if placing the item leaves the bin at least 98% full, else -1."""
    fill_after = (capacity - bins + item) / capacity
    return np.where(fill_after >= 0.98, 1.0, -1.0)

import numpy as np

def feature(item, bins, capacity):
    """Residual shape: max(-residual/capacity, (residual - item)/capacity), rewarding residual near 0 or >= item."""
    residual = bins - item
    return np.maximum(-residual / capacity, (residual - item) / capacity)

import numpy as np

def feature(item, bins, capacity):
    """Negative residual fraction after placement, minus 0.5 if that residual lies in the dead zone (0, 0.5*capacity)."""
    r = (bins - item) / capacity
    dead = ((r > 0) & (r < 0.5)).astype(float)
    return np.clip(-r - 0.5 * dead, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Size-gated fit: for large items (>= half capacity) tightest fit plus a bonus when leftover >= half capacity; for small items, spread (prefer more residual)."""
    r = (bins - item) / capacity
    large = item >= 0.5 * capacity
    if large:
        return np.clip(-r + 0.3 * (r >= 0.5), -1.0, 1.0)
    return np.clip(r, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Symmetric valley on post-placement residual fraction r=(bins-item)/capacity: -4*min(r, 0.5-r), clipped to [-1,1]."""
    r = (bins - item) / capacity
    valley = -4.0 * np.minimum(r, 0.5 - r)
    return np.clip(valley, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Indicator (1.0) when post-placement residual fraction lies strictly in (0.5, 0.8), else 0.0."""
    after = (bins - item) / capacity
    return ((after > 0.5) & (after < 0.8)).astype(float)

import numpy as np

def feature(item, bins, capacity):
    """Saturated step of post-placement residual fraction, scaled by the item's own size share: (1/(1+exp((0.5-after)*20))-0.5) * (item/capacity)."""
    after = (bins - item) / capacity
    step = 1.0 / (1.0 + np.exp((0.5 - after) * 20.0)) - 0.5
    return step * (item / capacity)

import numpy as np

def feature(item, bins, capacity):
    """1.0 for bins that complete (post-placement residual <= 3% of capacity), else the negative post-placement residual fraction."""
    r = np.clip((bins - item) / capacity, -1.0, 1.0)
    return np.where(r <= 0.03, 1.0, -r)

import numpy as np

def feature(item, bins, capacity):
    """Penalise the new bin (-1) only when some open bin fits the item with <=20% capacity slack; else 0."""
    val = np.zeros(len(bins))
    if len(bins) > 1:
        slack = bins[:-1] - item
        if np.min(slack) <= 0.2 * capacity:
            val[-1] = -1.0
    return val

import numpy as np

def feature(item, bins, capacity):
    """Normalised bin age: 0 for the oldest open bin, 1 for the new (last) bin."""
    k = bins.shape[0]
    return np.arange(k, dtype=float) / max(k - 1.0, 1.0)
